{
  "a_sentences": [
    {
      "a_text": "Regelmässig ausbezahlte Überstunden- und Ferienentschädigungen sind grundsätzlich Lohnbestandteile im Sinne von Art. 5 Abs. 2 AHVG und bei der Bemessung des Valideneinkommens zu berücksichtigen (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Für die Ermittlung des Valideneinkommens zog die Vorinstanz die IK-Einkünfte der Jahre 2015 bis 2019 heran, da das zuletzt erzielte Einkommen starke und kurzfristige Schwankungen aufwies (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Der Durchschnittsverdienst und damit der Validenlohn für das Jahr 2021 beträgt Fr. 103'472.32 und nicht Fr. 107'000.-, selbst wenn die geltend gemachte Ferien- und Überzeitentschädigung hinzugerechnet würde (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Die Anwendung von Kompetenzniveau 2 für das Invalideneinkommen ist gerechtfertigt, wenn die versicherte Person besondere Fertigkeiten und Kenntnisse wie Führungserfahrung oder zusätzliche formale Weiterbildungen besitzt (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Die Frage, ob ein Abzug vom Tabellenlohn vorzunehmen ist, ist eine frei überprüfbare Rechtsfrage (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Das Bundesgericht sieht keine Bundesrechtswidrigkeit in der vorinstanzlichen Ermittlung des Invalideneinkommens und der Verneinung eines leidensbedingten Abzugs (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Ein leidensbedingter Abzug ist nicht gerechtfertigt, da die gesundheitlichen Einschränkungen bereits im Zumutbarkeitsprofil berücksichtigt sind und keine quantitative Arbeitsunfähigkeit besteht (P7).",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Bei Gegenüberstellung der Einkommen resultiert ein Invaliditätsgrad von 30,50 % bzw. 37,67 %, der keinen Anspruch auf eine Invalidenrente begründet (P8).",
      "b_propositions": ["P8"]
    }
  ]
}
